properties.query:
// Source: Splunk — Excessive Failed VPN Logins
let lookback = ago(30m);
let threshold = 10;
CommonSecurityLog
| where TimeGenerated >= lookback
| where DeviceVendor == "Cisco"
| where DeviceEventClassID == "vpn-login-failed"
| summarize failures = count() by SourceUserName, SourceIP
| where failures > threshold
| project SourceUserName, SourceIP, failures
